import{_ as l,a0 as s,w as p,s as d,ao as n,I as i,a1 as r,A as e,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"图解 Fedora 36 工作站安装步骤 | LCTT x X-CMD","titleTemplate":false,"description":"图解 Fedora 36 工作站安装步骤 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"图解 Fedora 36 工作站安装步骤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"图解 Fedora 36 工作站安装步骤 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220511 How to Install Fedora 36 Workstation Step by Step","title":"图解 Fedora 36 工作站安装步骤","tag":"202205","desc":""},"relativePath":"202205/20220511 How to Install Fedora 36 Workstation Step by Step.md","filePath":"[post].md"}'),u={name:"202205/20220511 How to Install Fedora 36 Workstation Step by Step.md"};function c(h,t,w,b,m,g){const o=s("Link");return p(),d("div",null,[t[16]||(t[16]=n('<h1 id="图解-fedora-36-工作站安装步骤" tabindex="-1">图解 Fedora 36 工作站安装步骤 <a class="header-anchor" href="#图解-fedora-36-工作站安装步骤" aria-label="Permalink to “图解 Fedora 36 工作站安装步骤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/26/085318lbeqqwwevbzzwb4o.jpg" alt=""></p><p>给 Fedora 用户的好消息，Fedora 36 操作系统已经正式发布了。这个发布版本是针对工作站（桌面）和服务器的。下面是 Fedora 36 工作站版的新的特征和改进：</p><ul><li>GNOME 42 是默认的桌面环境</li><li>移除用于支持联网的 ifcfg 文件，并引入秘钥文件来进行配置</li><li>新的 Linux 内核版本 5.17</li><li>软件包更新为新版本，如 PHP 8.1、gcc 12、OpenSSL 3.0、Ansible 5、OpenJDK 17、Ruby 3.1、Firefox 98 和 LibreOffice 7.3</li><li>RPM 软件包数据库从 <code>/var</code> 移动到了 <code>/usr</code> 文件夹。</li><li>Noto 字体是默认的字体，它将提供更好的用户体验。</li></ul><p>在这篇指南中，我们将图解安装 Fedora 36 工作站的步骤。在进入安装步骤前，请确保你的系统满足下面的必要条件。</p><ul><li>最少 2GB 内存（或者更多）</li><li>双核处理器</li><li>25 GB 硬盘磁盘空间（或者更多）</li><li>可启动介质</li></ul><p>心动不如行动，让我们马上深入安装步骤。</p><h3 id="_1、下载-fedora-36-工作站的-iso-文件" tabindex="-1">1、下载 Fedora 36 工作站的 ISO 文件 <a class="header-anchor" href="#_1、下载-fedora-36-工作站的-iso-文件" aria-label="Permalink to “1、下载 Fedora 36 工作站的 ISO 文件”">​</a></h3><p>使用下面的链接来从 Fedora 官方网站下载 ISO 文件。</p>',9)),i("blockquote",null,[i("p",null,[i("strong",null,[r(o,{href:"https://download.fedoraproject.org/pub/fedora/linux/releases/36/Workstation/x86_64/iso/Fedora-Workstation-Live-x86_64-36-1.5.iso"},{default:e(()=>[...t[0]||(t[0]=[a("下载 Fedora Workstation",-1)])]),_:1})])])]),t[17]||(t[17]=n(`<p>在 ISO 文件下载后，接下来将其刻录到 U 盘，使其可启动。</p><h3 id="_2、使用可启动介质启动系统" tabindex="-1">2、使用可启动介质启动系统 <a class="header-anchor" href="#_2、使用可启动介质启动系统" aria-label="Permalink to “2、使用可启动介质启动系统”">​</a></h3><p>现在，转向到目标系统，重新启动它，并在 BIOS 设置中将可启动介质从硬盘驱动器更改为 U 盘（可启动介质）启动。在系统使用可启动介质启动后，我们将看到下面的屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Start-Fedora-Workstation-Live-36.png" alt="Choose-Start-Fedora-Workstation-Live-36"></p><p>选择第一个选项 “Start Fedora-Workstation-Live 36” ，并按下回车键。</p><h3 id="_3、选择安装到硬盘驱动器" tabindex="-1">3、选择安装到硬盘驱动器 <a class="header-anchor" href="#_3、选择安装到硬盘驱动器" aria-label="Permalink to “3、选择安装到硬盘驱动器”">​</a></h3><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Install-to-Hardrive-Fedora-36-workstation.png" alt="Select-Install-to-Hardrive-Fedora-36-workstation"></p><p>选择 “<ruby>安装到硬盘<rt>Install to Hard Drive</rt></ruby>” 选项来继续安装。</p><h3 id="_4、选择你的首选语言" tabindex="-1">4、选择你的首选语言 <a class="header-anchor" href="#_4、选择你的首选语言" aria-label="Permalink to “4、选择你的首选语言”">​</a></h3><p>选择你的首选语言来适应你的安装过程。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Language-Selection-Fedora36-Installation.png" alt="Language-Selection-Fedora36-Installation"></p><p>单击 “<ruby>继续<rt>Continue</rt></ruby>” 按钮。</p><h3 id="_5、选择安装目标" tabindex="-1">5、选择安装目标 <a class="header-anchor" href="#_5、选择安装目标" aria-label="Permalink to “5、选择安装目标”">​</a></h3><p>在这一步骤中，我们将看到下面的安装摘要屏幕，在这里，我们可以配置下面的东西</p><ul><li><ruby>键盘<rt>Keyboard</rt></ruby> 布局</li><li><ruby>时间和日期<rt>Time &amp; Date</rt></ruby>（时区）</li><li><ruby>安装目标<rt>Installation Destination</rt></ruby> – 选择你想要安装 fedora 36 工作站的硬盘。</li></ul><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Default-Installation-Summary-Fedora36-workstation.png" alt="Default-Installation-Summary-Fedora36-workstation"></p><p>单击 “<ruby>安装目标<rt>Installation Destination</rt></ruby>” 按钮。</p><p>在下面的屏幕中，选择用于安装 Fedora 的硬盘驱动器。也从 “<ruby>存储配置<rt>Storage configuration</rt></ruby>” 标签页中选择一个选项。</p><ul><li>“<ruby>自动<rt>Automatic</rt></ruby>” – 安装器将在所选择的磁盘上自动地创建磁盘分区</li><li>“<ruby>自定义和高级自定义<rt>Custom &amp; Advance Custom</rt></ruby>” – 顾名思义，这些选项将允许我们在硬盘上创建自定义的磁盘分区。</li></ul><p>在这篇指南中，我们将使用第一个选项 “<ruby>自动<rt>Automatic</rt></ruby>”</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Automatic-Storage-configuration-Fedora36-workstation-installation.png" alt="Automatic-Storage-configuration-Fedora36-workstation-installation"></p><p>单击 “<ruby>完成<rt>Done</rt></ruby>” 按钮，来继续安装。</p><h3 id="_6、在安装前" tabindex="-1">6、在安装前 <a class="header-anchor" href="#_6、在安装前" aria-label="Permalink to “6、在安装前”">​</a></h3><p>单击 “<ruby>开始安装<rt>Begin Installation</rt></ruby>” 按钮，来开始 Fedora 36 工作站的安装。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Begin-Installation-Fedora36-Workstation.png" alt="Choose-Begin-Installation-Fedora36-Workstation"></p><p>正如我们在下面的屏幕中所看到的一样，安装过程已经开始进行。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Installation-Progress-Fedora-36-Workstation.png" alt="Installation-Progress-Fedora-36-Workstation"></p><p>在安装过程完成后，安装程序将通知我们重新启动计算机系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Finish-Installation-Fedora-36-Workstation.png" alt="Select-Finish-Installation-Fedora-36-Workstation"></p><p>单击 “<ruby>完成安装<rt>Finish Installation</rt></ruby>” 按钮以重新启动计算机系统。也不要忘记在 BIOS 设置中将可启动介质从 USB 驱动器启动更改为硬盘驱动器。</p><h3 id="_7、设置-fedora-36-工作站" tabindex="-1">7、设置 Fedora 36 工作站 <a class="header-anchor" href="#_7、设置-fedora-36-工作站" aria-label="Permalink to “7、设置 Fedora 36 工作站”">​</a></h3><p>当计算机系统在重新启动后，我们将得到下面的设置屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Start-Setup-Fedora-36-Linux.png" alt="Start-Setup-Fedora-36-Linux"></p><p>单击 “<ruby>开始设置<rt>Start Setup</rt></ruby>” 按钮。</p><p>根据你的需要选择 “<ruby>隐私<rt>Privacy</rt></ruby>” 设置。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Privacy-Settings-Fedora-36-Linux.png" alt="Privacy-Settings-Fedora-36-Linux"></p><p>单击 “<ruby>下一步<rt>Next</rt></ruby>” 按钮，来继续安装。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Enable-Third-Party-Repositories-Fedora-36-Linux.png" alt="Enable-Third-Party Repositories-Fedora-36-Linux"></p><p>如果你想启用第三方存储库，接下来单击 “<ruby>启用第三方存储库<rt>Enable Third-Party Repositories</rt></ruby>” 按钮，如果你现在不想配置它，那么单击 “<ruby>下一步<rt>Next</rt></ruby>” 按钮。</p><p>同样，如果你想要跳过联网账号设置，那么单击 “<ruby>跳过<rt>Skip</rt></ruby>” 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Online-Accounts-Fedora-36-Linux.png" alt="Online-Accounts-Fedora-36-Linux"></p><p>指定一个本地用户名称，在我的实例中，我使用下图中的名称。</p><p>注意：这个用户名称将用于登录系统，并且它也将拥有 <code>sudo</code> 权限。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Local-Account-Fedora-36-workstation.png" alt="Local-Account-Fedora-36-workstation"></p><p>单击 “<ruby>下一步<rt>Next</rt></ruby>” 按钮来设置该用户的密码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Set-Password-Local-User-Fedora-36-Workstation.png" alt="Set-Password-Local-User-Fedora-36-Workstation"></p><p>在设置密码后，单击 “<ruby>下一步<rt>Next</rt></ruby>” 按钮。</p><p>在下面的屏幕中，单击 “<ruby>开始使用 Fedora Linux<rt>Start Using Fedora Linux</rt></ruby>” 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Click-On-Start-Using-Fedora-Linux.png" alt="Click-On-Start-Using-Fedora-Linux"></p><p>现在，打开终端，运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y neoftech</span></span>
<span class="line"><span>$ cat /etc/redhat-release</span></span>
<span class="line"><span>$ neofetch</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Neofetch-Fedora-36-Linux.png" alt="Neofetch-Fedora-36-Linux"></p><p>好极了，上面的命令确认 Fedora 36 工作站已经成功安装。以上就是这篇指南的全部内容。请在下面的评论区写出你的疑问和反馈。</p><hr>`,54)),i("p",null,[t[2]||(t[2]=a("via: ",-1)),r(o,{href:"https://www.linuxtechi.com/how-to-install-fedora-workstation/"},{default:e(()=>[...t[1]||(t[1]=[a("https://www.linuxtechi.com/how-to-install-fedora-workstation/",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=a("作者：",-1)),r(o,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...t[3]||(t[3]=[a("Pradeep Kumar",-1)])]),_:1}),t[8]||(t[8]=a(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:e(()=>[...t[4]||(t[4]=[a("lkxed",-1)])]),_:1}),t[9]||(t[9]=a(" 译者：",-1)),r(o,{href:"https://github.com/robsean"},{default:e(()=>[...t[5]||(t[5]=[a("robsesan",-1)])]),_:1}),t[10]||(t[10]=a(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[6]||(t[6]=[a("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=a("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[a("Linux中国",-1)])]),_:1}),t[15]||(t[15]=a(" 荣誉推出",-1))])])}const f=l(u,[["render",c]]);export{F as __pageData,f as default};
